const SORTS={seq:'ترتیب ثبت (ردیف)',new:'آخرین ثبت، اول',amtD:'مبلغ: بیشترین اول',amtA:'مبلغ: کمترین اول',name:'نام (الفبا)',bank:'بانک مقصد',err:'خطادارها اول'};
