      <div class="wzafter"><span>${d.st==='wait'?'مانده فعلاً تغییر نمی‌کند':'مانده بعد از این واریز'}</span><b style="color:${after>0?'var(--red)':'var(--ok)'}">${after>0?fmt(after)+' تومان':'تسویه کامل ✓'}</b></div>
