  if(L.length===1){const iso=L[0];ldKey=iso;const P=parts(iso).filter(p=>(p.ids||[]).length);txtGen=null;expCtx={A:partsAlloc(P),sc:P.length>1?'all':'0',track:true,parts:P.filter(p=>!p.sent).map(p=>p.id)};}
