/* ---------- لیست واحد: ارسال، تأیید گروهی، بایگانی ---------- */
/* تخصیص قدیمی که ردیف‌هایی از تاریخ واریز دیگر هم دارد، موقع ارسال جدا می‌شود تا هر بخش در لیست خودش بماند */
function partOwnPay(p){const M=vMap(),other={};p.ids.forEach(id=>{const r=M.get(id);if(r&&PD(r)!==ldKey)(other[PD(r)]=other[PD(r)]||[]).push(id)});
  Object.keys(other).forEach(k=>{const ids=other[k];p.ids=p.ids.filter(id=>!ids.includes(id));addPart({...p,id:nid++,ids,sent:false,bid:undefined,param:{...(p.param||{})}},k)});p.pay=ldKey}
async function hubSendParts(P){P=P.filter(p=>!p.sent&&p.ids.length);if(!P.length)return;P.forEach(partOwnPay);saveD();txtGen=null;
  const A=partsAlloc(P),sc=P.length>1?'all':'0';expCtx={A,sc};const ok=await copyText(withCtx(txt)),ids=P.map(p=>p.id),b=commitParts(ids,true);
  if(!ok){expCtx={A,sc};openText();toast('ارسال شد؛ متن را از اینجا کپی کنید');return}
  toast('متن کپی شد و '+fmt(P.reduce((a,p)=>a+p.ids.length,0))+' واریزی ارسال شد','','برگرداندن',()=>uncommitParts(ids));if(b){const v=$('view'),y=v.scrollTop;render();v.scrollTop=y}}
ACT.hubSend=d=>hubSendParts(parts().filter(p=>p.src.name===d.k));
ACT.hubSendAll=()=>hubSendParts(parts());
/* باز و بسته شدن منبع بدون ساختن دوباره صفحه؛ حرکت کوتاه با CSS (با «کاهش حرکت» حذف می‌شود) */
ACT.hubTog=(d,e)=>{const el=e&&e.target.closest('.hubg');const g=hubData(ldKey).G.find(z=>z.name===d.k),o=d.k==='__full'?!hubOpen.get('__full'):!(g&&hubIsOpen(g));hubOpen.set(d.k,o);if(el){el.classList.toggle('open',o);const b=el.querySelector('.ldm');if(b)b.setAttribute('aria-expanded',o)}else{const v=$('view'),y=v.scrollTop;render();v.scrollTop=y}};
ACT.hubOkAll=d=>{const g=hubData(ldKey).G.find(z=>z.name===d.k);if(!g)return;const L=g.rows.filter(z=>z.bi&&z.st==='pending'&&!z.bi.b.closed).map(z=>z.bi.x);if(!L.length)return;const now=new Date().toISOString();L.forEach(x=>{x.st='ok';x.at=now});saveB();logA('track','تأیید گروهی',d.k+' | '+fmt(L.length)+' واریزی');const v=$('view'),y=v.scrollTop;render();v.scrollTop=y;toast(fmt(L.length)+' واریز تسویه شد','','برگرداندن',()=>{L.forEach(x=>x.st='pending');saveB();render()})};
/* بایگانی یک لیست: پیگیری‌هایی که فقط ردیف همین لیست را دارند بسته می‌شوند؛ پیگیری قدیمی مشترک بین چند لیست، ردیف‌های این لیست را به پیگیری جدید می‌دهد (کلید عکس‌ها همراه ردیف می‌رود) */
function hubClose(k){const M=vMap(),now=new Date().toISOString(),inK=x=>{const r=M.get(x.id);return r?PD(r)===k:(x.pay||'')===k},touched=[];
  batches.filter(b=>!b.closed&&b.items.some(inK)).forEach(b=>{let t=b;
    if(!b.items.every(inK)){const mv=b.items.filter(inK);mv.forEach(x=>{x.imgs=itImgs(b,x)});t={id:nid++,date:k,pay:k,createdAt:now,by:who(),items:mv};b.items=b.items.filter(x=>!inK(x));batches.unshift(t);
      const S=new Set(mv.map(x=>x.id));entries.forEach(e=>{if(S.has(e.id)&&e.sentBid===b.id)e.sentBid=t.id});allParts().forEach(p=>{if(p.bid===b.id&&p.ids.length&&p.ids.every(id=>S.has(id)))p.bid=t.id})}
    const c=bStat(t);t.closed=now;t.arch={ok:c.ok,fail:c.fail,pending:c.pending,all:c.all,okSum:c.okSum||0,by:who()};touched.push(t)});
  saveE();saveB();saveD();return touched}
ACT.hubArch=()=>{const d=hubData(ldKey);if(!d.sent)return;const go2=()=>{const T=hubClose(ldKey);logA('close','بایگانی لیست',pdHead(ldKey)+' | موفق '+fmt(d.ok)+' از '+fmt(d.rows.length));const v=$('view'),y=v.scrollTop;render();v.scrollTop=y;toast(T.length?'لیست بایگانی شد':'چیزی برای بایگانی نبود')};
  d.pend||d.un.length||d.dr.length?askConfirm([d.pend?fmt(d.pend)+' واریزی هنوز «در انتظار» است':'',d.un.length||d.dr.length?fmt(d.un.length+d.none)+' واریزی هنوز ارسال نشده':''].filter(Boolean).join(' و ')+'. با همین وضعیت بایگانی شود؟','بایگانی',go2):go2()};
ACT.hubReopen=()=>{const M=vMap();let n=0;batches.forEach(b=>{if(b.closed&&b.items.some(x=>{const r=M.get(x.id);return r?PD(r)===ldKey:x.pay===ldKey})){delete b.closed;n++}});saveB();logA('close','بازگشایی لیست',pdHead(ldKey));render();toast(n?'لیست برای ویرایش باز شد':'لیست بسته‌ای نبود')};
/* ---------- عکس رسیدها: چند عکس برای هر واریز بانکی و هر تسویه مشتری، ویرایش (چرخش و برش) و بزرگ‌نمایی داخل برنامه ---------- */
/* کلید عکس‌ها روی خود ردیف ذخیره می‌شود (imgs)؛ ردیف‌های قدیمی که فقط img دارند همان کلید قبلی را نگه می‌دارند */
const itImgs=(b,x)=>Array.isArray(x.imgs)?x.imgs.slice():x.img?[ikey(b,x)]:[];
const stImgs=z=>Array.isArray(z.imgs)?z.imgs.slice():z.img&&typeof z.img==='string'?[z.img]:[];
const newImgKey=p=>p+':'+Date.now().toString(36)+Math.random().toString(36).slice(2,6);
let GAL=null;
/* صاحب عکس‌ها: {k:'it',eid} = رسید واریز بانکی یک واریزی، {k:'st',eid,sid} = رسید یک تسویه مشتری */
function galCtx(){if(!GAL)return null;const e=entries.find(z=>String(z.id)===String(GAL.eid));if(!e)return null;const now=()=>new Date().toISOString();
  if(GAL.k==='it'){const q=entBI(e);if(!q)return null;/* رسید حتی بعد از تأیید و بایگانی لیست هم اضافه می‌شود؛ وضعیت واریز در لیست بسته تغییر نمی‌کند */
    return{keys:itImgs(q.b,q.it),ed:can('track'),pre:'rc:'+e.id,
    set:K=>{q.it.imgs=K;q.it.img=K.length>0;q.it.at=now();saveB()},
    meta:{name:fullName(e),holder:e.holder||fullName(e),amount:q.it.amount,tn:q.it.tn||'',src:q.it.src||'',date:PD(e),kind:'bank'}}}
  const z=(e.settles||[]).find(s=>String(s.id)===String(GAL.sid));if(!z)return null;
  return{keys:stImgs(z),ed:can('edit'),pre:'stl:'+z.id,
    set:K=>{z.imgs=K;z.img=K[0]||'';e.updatedAt=now();e.updatedBy=who();saveE();stlSync(e)},
    meta:{name:fullName(e)+' (از '+z.name+')',holder:e.holder||fullName(e),payer:z.name,amount:z.amount,tn:z.tn||'',date:z.date,kind:'cust'}}}
function galHTML(){const c=galCtx();if(!c)return `<div class="sh-h"><b>رسید</b><button class="x" data-act="close" aria-label="بستن">×</button></div><div class="spempty"><b>پیدا نشد</b></div>`;const K=c.keys;
  return `<div class="sh-h"><div><b>${GAL.k==='it'?'رسید واریز بانکی':'رسید تسویه مشتری'}</b><small class="shsub">${esc(c.meta.name)} · ${fmt(c.meta.amount)} تومان${K.length?' · '+fmt(K.length)+' عکس':''}</small></div><button class="x" data-act="close" aria-label="بستن">×</button></div>
  <div class="galg">${K.map((k,i)=>`<button class="galt" data-act="galView" data-i="${i}" aria-label="دیدن عکس ${toFa(i+1)}"><span class="galim" id="gal${i}"></span><i>${toFa(i+1)}</i></button>`).join('')}${c.ed?`<label class="galt add">${ic('plus')}<span>${K.length?'عکس دیگر':'افزودن عکس'}</span><input type="file" accept="image/*" multiple data-galadd="1" hidden></label>`:''}</div>
  ${!K.length?`<div class="galnote">${c.ed?'می‌توانید چند عکس با هم انتخاب کنید؛ هر عکس را بعداً بزرگ کنید، بچرخانید یا برش بزنید.':'برای این واریز عکسی ثبت نشده است.'}</div>`:`<div class="galnote">برای بزرگ‌نمایی، چرخش یا برش روی عکس بزنید.</div><div class="txacts"><button data-act="galShare">${ic('open')} اشتراک${K.length>1?' همه':''}</button><button data-act="galSave">${ic('down')} ذخیره${K.length>1?' همه':''}</button></div>`}`}
function openGal(ref){GAL=ref;sheet(galHTML());galThumbs()}
function galThumbs(){const c=galCtx();if(!c)return;c.keys.forEach(async(k,i)=>{const d=await imgGet(k),el=$('gal'+i);if(el&&d)el.style.backgroundImage=`url(${d})`})}
function galRefresh(){if(!$('ov').classList.contains('hide')&&GAL&&$('sheet').querySelector('.galg'))$('sheet').innerHTML=galHTML(),galThumbs();if(['ent','lday','part','batch','day'].includes(cur)){const v=$('view'),y=v.scrollTop;render();v.scrollTop=y}}
const galFiles=c=>c.keys.map(k=>({key:k,...c.meta}));
document.addEventListener('change',async ev=>{const t=ev.target;if(!t||!t.dataset||t.dataset.galadd==null)return;const F=[...(t.files||[])];t.value='';if(!F.length)return;const c=galCtx();if(!c||!c.ed)return;
  const K=c.keys;let n=0;for(const f of F){try{const d=await shrink(f),k=newImgKey(c.pre);if(await imgPut(k,d)){K.push(k);n++}else{toast('حافظه پر است؛ عکس ذخیره نشد',true);break}}catch(e){toast('این عکس خوانده نشد',true)}}
  if(n){galCtx().set(K);logA('edit','افزودن رسید',c.meta.name+' | '+fmt(n)+' عکس');galRefresh();toast(n>1?fmt(n)+' عکس اضافه شد':'عکس اضافه شد')}});
ACT.galIt=d=>{const e=entries.find(z=>String(z.id)===String(d.id));if(!e||!entBI(e)){toast('این واریزی هنوز ارسال نشده است',true);return}openGal({k:'it',eid:e.id})};
ACT.galSt=d=>{const e=stlE(),z=e&&(e.settles||[])[+d.i];if(!z)return;openGal({k:'st',eid:e.id,sid:z.id})};
ACT.galView=d=>zvOpen(+d.i);
ACT.galShare=async()=>{const c=galCtx();if(c)rcShare(await rcFiles(galFiles(c)),'رسید '+c.meta.name)};
ACT.galSave=async()=>{const c=galCtx();if(c)rcDown(await rcFiles(galFiles(c)))};
/* ---------- نمایش تمام‌صفحه: دو انگشت یا دو بار زدن برای بزرگ‌نمایی، کشیدن برای جابه‌جایی ---------- */
let ZV=null;
function zvEl(){let z=$('zv');if(!z){z=document.createElement('div');z.id='zv';z.className='zv hide';z.setAttribute('role','dialog');z.setAttribute('aria-label','نمایش عکس');document.body.appendChild(z);zvBind(z)}return z}
async function zvOpen(i){const c=galCtx();if(!c||!c.keys.length)return;i=Math.max(0,Math.min(c.keys.length-1,i));ZV={i,k:c.keys[i],s:1,x:0,y:0,crop:null};const z=zvEl();z.classList.remove('hide');zvBar();const v=await imgGet(ZV.k);const im=$('zvi');if(!v){toast('عکس پیدا نشد',true);zvClose();return}if(im&&ZV&&ZV.k===c.keys[i]){im.src=v;ZV.src=v}}
function zvBar(){const c=galCtx(),z=zvEl();if(!c||!ZV)return;const n=c.keys.length,ed=c.ed;
  z.innerHTML=`<div class="zvt"><button class="zb" data-act="zvClose" aria-label="بستن">×</button><span class="zc">${toFa(ZV.i+1)} از ${toFa(n)}</span><span class="zsp"></span>${ZV.crop?`<button class="zb t" data-act="zvCropNo">انصراف</button><button class="zb t pri" data-act="zvCropOk">${ic('check')} برش</button>`:`${ed?`<button class="zb" data-act="zvRot" aria-label="چرخش">${ic('undo')}</button><button class="zb" data-act="zvCrop" aria-label="برش">${ZCROP}</button><button class="zb" data-act="zvDel" aria-label="حذف">${ic('trash')}</button>`:''}<button class="zb" data-act="zvShare" aria-label="اشتراک">${ic('open')}</button>`}</div>
  <div class="zvs" id="zvs"><img id="zvi" alt="رسید" draggable="false"${ZV.src?` src="${ZV.src}"`:''}>${ZV.crop?'<div class="zcr" id="zcr"><i data-h="nw"></i><i data-h="ne"></i><i data-h="sw"></i><i data-h="se"></i></div>':''}</div>
  ${n>1&&!ZV.crop?`<div class="zvn"><button class="zb" data-act="zvGo" data-d="-1" aria-label="قبلی"${ZV.i?'':' disabled'}>${ic('back')}</button><span>${esc(c.meta.name)}</span><button class="zb" data-act="zvGo" data-d="1" aria-label="بعدی"${ZV.i<n-1?'':' disabled'}>${ic('back').replace('class="i"','class="i flip"')}</button></div>`:`<div class="zvn"><span>${esc(c.meta.name)} · ${fmt(c.meta.amount)} تومان</span></div>`}`;
  zvApply();if(ZV.crop)requestAnimationFrame(zvCropInit)}
const ZCROP='<svg class="i" viewBox="0 0 24 24" aria-hidden="true"><path d="M6 2v14a2 2 0 0 0 2 2h14M2 6h14a2 2 0 0 1 2 2v14"/></svg>';
function zvApply(){const im=$('zvi');if(im&&ZV)im.style.transform=`translate(${ZV.x}px,${ZV.y}px) scale(${ZV.s})`}
function zvClose(){ZV=null;const z=$('zv');if(z){z.classList.add('hide');z.innerHTML=''}}
function zvClamp(){const s=$('zvs'),im=$('zvi');if(!s||!im||!ZV)return;if(ZV.s<=1){ZV.s=1;ZV.x=0;ZV.y=0;return}const W=im.offsetWidth*ZV.s,H=im.offsetHeight*ZV.s,mx=Math.max(0,(W-s.clientWidth)/2),my=Math.max(0,(H-s.clientHeight)/2);ZV.x=Math.max(-mx,Math.min(mx,ZV.x));ZV.y=Math.max(-my,Math.min(my,ZV.y))}
function zvBind(z){const P=new Map();let st=null,lastTap=0;
  z.addEventListener('pointerdown',e=>{if(!ZV||ZV.crop||!e.target.closest('#zvs'))return;z.classList.add('drag');z.setPointerCapture&&z.setPointerCapture(e.pointerId);P.set(e.pointerId,{x:e.clientX,y:e.clientY});
    if(P.size===2){const [a,b]=[...P.values()];st={d:Math.hypot(a.x-b.x,a.y-b.y),s:ZV.s,x:ZV.x,y:ZV.y,cx:(a.x+b.x)/2,cy:(a.y+b.y)/2}}else{st={px:e.clientX,py:e.clientY,x:ZV.x,y:ZV.y,moved:false}}});
  z.addEventListener('pointermove',e=>{if(!ZV||!P.has(e.pointerId)||!st)return;P.set(e.pointerId,{x:e.clientX,y:e.clientY});
    if(P.size===2&&st.d){const [a,b]=[...P.values()],d=Math.hypot(a.x-b.x,a.y-b.y);ZV.s=Math.max(1,Math.min(6,st.s*d/st.d));const cx=(a.x+b.x)/2,cy=(a.y+b.y)/2;ZV.x=st.x+(cx-st.cx);ZV.y=st.y+(cy-st.cy);zvClamp();zvApply();return}
    if(P.size===1&&st.px!=null){const dx=e.clientX-st.px,dy=e.clientY-st.py;if(Math.abs(dx)+Math.abs(dy)>6)st.moved=true;if(ZV.s>1){ZV.x=st.x+dx;ZV.y=st.y+dy;zvClamp();zvApply()}}});
  const up=e=>{if(!ZV||!P.has(e.pointerId))return;P.delete(e.pointerId);if(!P.size)z.classList.remove('drag');
    if(!P.size&&st&&st.px!=null){const dx=e.clientX-st.px,dy=e.clientY-st.py;if(st.moved&&ZV.s<=1&&dy>90&&Math.abs(dy)>Math.abs(dx)*1.5){zvClose();return}
      if(!st.moved){const t=Date.now();if(t-lastTap<300){const s=$('zvs'),r=s.getBoundingClientRect();if(ZV.s>1){ZV.s=1;ZV.x=0;ZV.y=0}else{ZV.s=2.5;ZV.x=(r.left+r.width/2-e.clientX)*1.5;ZV.y=(r.top+r.height/2-e.clientY)*1.5;zvClamp()}zvApply();lastTap=0}else lastTap=t}
      else if(ZV.s<=1&&Math.abs(dx)>60){const c=galCtx();if(c){const ni=ZV.i+(dx<0?1:-1);if(ni>=0&&ni<c.keys.length)zvOpen(ni)}}}
    if(P.size<2)st=P.size===1?(()=>{const p=[...P.values()][0];return{px:p.x,py:p.y,x:ZV.x,y:ZV.y,moved:true}})():null};
  z.addEventListener('pointerup',up);z.addEventListener('pointercancel',up);
  z.addEventListener('wheel',e=>{if(!ZV||ZV.crop)return;e.preventDefault();ZV.s=Math.max(1,Math.min(6,ZV.s*(e.deltaY<0?1.15:1/1.15)));zvClamp();zvApply()},{passive:false})}
ACT.zvClose=()=>zvClose();
ACT.zvGo=d=>{if(ZV)zvOpen(ZV.i+(+d.d))};
ACT.zvShare=async()=>{const c=galCtx();if(!c||!ZV)return;rcShare(await rcFiles([{key:ZV.k,...c.meta}]),'رسید '+c.meta.name)};
ACT.zvDel=()=>{const c=galCtx();if(!c||!ZV)return;const k=ZV.k,i=ZV.i;askConfirm('این عکس حذف شود؟','حذف عکس',async()=>{const K=c.keys.filter(z=>z!==k);c.set(K);await imgDel(k);logA('edit','حذف رسید',c.meta.name);galRefresh();if(K.length)zvOpen(Math.min(i,K.length-1));else zvClose();toast('عکس حذف شد')})};
/* ویرایش: نسخه جدید روی همان کلید ذخیره می‌شود؛ نسخه قبلی روی سرور ۹۰ روز نگه داشته می‌شود و تا چند ثانیه «برگرداندن» دارد */
function zvLoad(src){return new Promise((res,rej)=>{const im=new Image();im.onload=()=>res(im);im.onerror=rej;im.src=src})}
async function zvSave(nd,msg){const c=galCtx();if(!c||!ZV)return;const k=ZV.k,old=ZV.src;if(!(await imgPut(k,nd))){toast('ذخیره نشد',true);return}c.set(c.keys);ZV.src=nd;ZV.s=1;ZV.x=0;ZV.y=0;ZV.crop=null;zvBar();galRefresh();
  toast(msg,'','برگرداندن',async()=>{await imgPut(k,old);if(ZV&&ZV.k===k){ZV.src=old;zvBar()}galRefresh()})}
ACT.zvRot=async()=>{if(!ZV||!ZV.src)return;const im=await zvLoad(ZV.src),c=document.createElement('canvas');c.width=im.height;c.height=im.width;const g=c.getContext('2d');g.translate(c.width,0);g.rotate(Math.PI/2);g.drawImage(im,0,0);zvSave(c.toDataURL('image/jpeg',.9),'عکس چرخید')};
ACT.zvCrop=()=>{if(!ZV||!ZV.src)return;ZV.s=1;ZV.x=0;ZV.y=0;ZV.crop={l:.05,t:.05,r:.95,b:.95};zvBar()};
ACT.zvCropNo=()=>{if(!ZV)return;ZV.crop=null;zvBar()};
ACT.zvCropOk=async()=>{if(!ZV||!ZV.crop)return;const k=ZV.crop,im=await zvLoad(ZV.src),W=im.naturalWidth,H=im.naturalHeight,x=Math.round(k.l*W),y=Math.round(k.t*H),w=Math.max(20,Math.round((k.r-k.l)*W)),h=Math.max(20,Math.round((k.b-k.t)*H)),c=document.createElement('canvas');c.width=w;c.height=h;c.getContext('2d').drawImage(im,x,y,w,h,0,0,w,h);zvSave(c.toDataURL('image/jpeg',.9),'عکس برش خورد')};
/* کادر برش: گوشه‌ها برای اندازه، وسط برای جابه‌جایی */
function zvCropInit(){const im=$('zvi'),cr=$('zcr');if(!im||!cr||!ZV||!ZV.crop)return;
  const place=()=>{const a=im.getBoundingClientRect(),s=$('zvs').getBoundingClientRect(),k=ZV.crop;cr.style.left=(a.left-s.left+k.l*a.width)+'px';cr.style.top=(a.top-s.top+k.t*a.height)+'px';cr.style.width=((k.r-k.l)*a.width)+'px';cr.style.height=((k.b-k.t)*a.height)+'px'};
  if(!im.complete){im.onload=place}place();let dr=null;
  cr.onpointerdown=e=>{e.stopPropagation();cr.setPointerCapture&&cr.setPointerCapture(e.pointerId);const a=im.getBoundingClientRect();dr={h:e.target.dataset.h||'m',x:e.clientX,y:e.clientY,k:{...ZV.crop},w:a.width,ht:a.height}};
  cr.onpointermove=e=>{if(!dr||!ZV)return;const dx=(e.clientX-dr.x)/dr.w,dy=(e.clientY-dr.y)/dr.ht,k={...dr.k},m=.08,cl=v=>Math.max(0,Math.min(1,v));
    if(dr.h==='m'){const w=k.r-k.l,h=k.b-k.t;k.l=cl(k.l+dx);k.t=cl(k.t+dy);if(k.l+w>1)k.l=1-w;if(k.t+h>1)k.t=1-h;k.r=k.l+w;k.b=k.t+h}
    else{if(dr.h.includes('w'))k.l=Math.min(cl(k.l+dx),k.r-m);if(dr.h.includes('e'))k.r=Math.max(cl(k.r+dx),k.l+m);if(dr.h.includes('n'))k.t=Math.min(cl(k.t+dy),k.b-m);if(dr.h.includes('s'))k.b=Math.max(cl(k.b+dy),k.t+m)}
    ZV.crop=k;place()};
  cr.onpointerup=cr.onpointercancel=()=>{dr=null}}
addEventListener('keydown',e=>{if(!ZV)return;if(e.key==='Escape')zvClose();else if(e.key==='ArrowLeft'||e.key==='ArrowRight')ACT.zvGo({d:e.key==='ArrowLeft'?1:-1})});
/* ---------- پرداخت یک واریزی از چند منبع ---------- */
/* واریزی به چند «بخش» مرتبط تقسیم می‌شود: خود واریزی (با تسویه‌های مشتری‌اش) + واریزی‌های همراه با splitOf.
   هر بخش یک واریزی کامل است که در منبع خودش تخصیص، ارسال، پیگیری و خروجی می‌شود. */
const famRoot=x=>x.splitOf!=null&&entries.some(e=>e.id===x.splitOf)?x.splitOf:x.id;
const famOf=x=>{const k=famRoot(x);return validated().filter(r=>r.id===k||r.splitOf===k).sort((a,b)=>(a.id===k?-1:b.id===k?1:a.id-b.id))};
function famSrc(r,A){const si=r.sentBid?srcInfo(r.id):null;if(si)return{name:si.src,st:si.st,sent:true};const a=A.get(r.id);return a&&a.src?{name:a.src,st:'none'}:null}
function entPieces(x){const F=famOf(x),sent=F.some(r=>r.sentBid),ok=can('split')&&!x.full&&x.level<2;if(F.length<2&&!(ok&&x.amount>0))return '';
  if(F.length<2)return `<div class="esec psplit"><div class="stlh"><div><b>پرداخت از چند منبع</b><small>اگر این مبلغ باید بخشی از یک بانک و بخشی از بانک دیگر پرداخت شود</small></div>${!sent?`<button class="stladd" data-act="paySplit" data-id="${x.id}">${ic('split')} تقسیم بین منابع</button>`:''}</div>${sent?'<div class="muted" style="font-size:12px">این واریزی ارسال شده؛ برای تقسیم اول از پیگیری برگردانید.</div>':''}</div>`;
  const tot=sum(F),root=famRoot(x),A=allocMap();
  return `<div class="esec psplit"><div class="stlh"><div><b>پرداخت از ${toFa(F.length)} منبع</b><small>جمع ${fmt(tot)} تومان · هر بخش جدا ارسال و پیگیری می‌شود</small></div>${ok&&!sent?`<button class="stladd" data-act="paySplit" data-id="${x.id}">${ic('edit')} تغییر</button>`:''}</div>
  <div class="stll2">${F.map((r,i)=>{const s=famSrc(r,A),me=r.id===x.id,st=s&&s.sent?(s.st==='ok'?['k','تسویه شد']:s.st==='fail'?['f','ناموفق']:['w','در انتظار']):s?['d','آماده ارسال']:['n','بدون منبع'];return `<div class="stlrw ${st[0]}${me?' me':''}"><button class="stlr" data-act="openEnt" data-id="${r.id}"><span class="bri"><b>${toFa(i+1)}</b></span><span class="tx"><b>${esc(s?s.name:'بدون منبع')}</b><small>${me?'همین بخش':r.id===root?'بخش اصلی':'بخش '+toFa(i+1)}</small></span><span class="brv"><b>${fmt(r.amount)} <i>تومان</i></b><small>${st[1]}</small></span></button></div>`}).join('')}</div>
  ${ok&&!sent?`<button class="link" data-act="paySplitUndo" data-id="${x.id}">یکی کردن بخش‌ها</button>`:''}</div>`}
let PS=null;
function psHTML(){const R=PS.R,s=PS.L.reduce((a,l)=>a+(+l.amount||0),0),left=R-s,opts=v=>`<option value="">بدون منبع</option>`+sources.map(z=>`<option value="${z.id}"${String(z.id)===String(v)?' selected':''}>${esc(z.name)}${acBank(z)?' · '+esc(acBank(z)):''}</option>`).join('');
  return `<div class="sh-h"><div><b>پرداخت از چند منبع</b><small class="shsub">${esc(PS.name)} · مبلغ بانکی ${fmt(R)} تومان</small></div><button class="x" data-act="close" aria-label="بستن">×</button></div>
  <div class="psl">${PS.L.map((l,i)=>`<div class="psr"><span class="n">${toFa(i+1)}</span><select data-ps="${i}" aria-label="منبع بخش ${toFa(i+1)}">${opts(l.src)}</select><input class="ltr num" data-pa="${i}" inputmode="numeric" value="${l.amount?Number(l.amount).toLocaleString('en-US'):''}" placeholder="مبلغ" aria-label="مبلغ بخش ${toFa(i+1)}">${PS.L.length>1?`<button class="psx" data-act="psDel" data-i="${i}" aria-label="حذف بخش">×</button>`:''}</div>`).join('')}</div>
  <button class="link" data-act="psAdd">${ic('plus')} بخش دیگر</button>
  <div class="pss ${left?'bad':'ok'}"><span>جمع بخش‌ها <b>${fmt(s)}</b></span><span>${left>0?'مانده <b>'+fmt(left)+'</b>':left<0?'بیشتر از مبلغ: <b>'+fmt(-left)+'</b>':'برابر مبلغ ✓'}</span>${left>0?`<button class="sm sec" data-act="psFill">بقیه به بخش آخر</button>`:''}</div>
  <div class="muted" style="font-size:12px;line-height:1.8;margin:8px 2px">هر بخش در لیست ${esc(pdHead(PS.pay))} زیر منبع خودش می‌آید و جدا کپی، ارسال و پیگیری می‌شود. نام، فاکتور و شبا برای همه بخش‌ها یکی است.</div>
  <button class="xgo" data-act="paySplitSave"${left||PS.L.some(l=>!(+l.amount>0))?' disabled':''}>${ic('check')} ثبت ${toFa(PS.L.length)} بخش</button>`}
function psRedraw(){const f=document.activeElement,fi=f&&f.dataset?(f.dataset.pa||null):null,pos=f&&f.selectionStart;$('sheet').innerHTML=psHTML();if(fi!=null){const n=document.querySelector(`#sheet [data-pa="${fi}"]`);if(n){n.focus();try{n.setSelectionRange(n.value.length,n.value.length)}catch(e){}}}}
function psBind(){const sh=$('sheet');sh.oninput=e=>{const t=e.target;if(t.dataset.pa!=null){const v=num(t.value);PS.L[+t.dataset.pa].amount=v;clearTimeout(sh._t);sh._t=setTimeout(psRedraw,350)}};sh.onchange=e=>{const t=e.target;if(t.dataset.ps!=null){PS.L[+t.dataset.ps].src=t.value;psRedraw()}if(t.dataset.pa!=null)psRedraw()}}
ACT.paySplit=d=>{const x=validated().find(r=>String(r.id)===String(d.id));if(!x)return;const F=famOf(x);if(F.some(r=>r.sentBid)){toast('یکی از بخش‌ها ارسال شده؛ اول از پیگیری برگردانید',true);return}
  AM=allocMap();const sid=n=>{const s=sources.find(z=>z.name===n);return s?String(s.id):''};
  const L=F.map(r=>{const a=AM.get(r.id);return{src:a&&a.src?sid(a.src):'',amount:r.amount}});if(L.length===1){const o=sources.find(z=>String(z.id)!==L[0].src);L[0].amount=0;L.push({src:o?String(o.id):'',amount:0})}
  PS={root:famRoot(x),name:fullName(x),pay:PD(x),R:sum(F),L};sheet(psHTML());psBind()};
ACT.psAdd=()=>{const used=new Set(PS.L.map(l=>l.src)),o=sources.find(z=>!used.has(String(z.id)));PS.L.push({src:o?String(o.id):'',amount:0});psRedraw()};
ACT.psDel=d=>{PS.L.splice(+d.i,1);psRedraw()};
ACT.psFill=()=>{const s=PS.L.slice(0,-1).reduce((a,l)=>a+(+l.amount||0),0);PS.L[PS.L.length-1].amount=Math.max(0,PS.R-s);psRedraw()};
ACT.paySplitUndo=d=>{const x=validated().find(r=>String(r.id)===String(d.id));if(!x)return;askConfirm('همه بخش‌ها دوباره یک واریزی شوند؟ تخصیص بخش‌ها برداشته می‌شود.','یکی کردن',()=>{const F=famOf(x);PS={root:famRoot(x),name:fullName(x),pay:PD(x),R:sum(F),L:[{src:'',amount:sum(F)}]};psApply()})};
ACT.paySplitSave=()=>{if(!PS)return;const s=PS.L.reduce((a,l)=>a+(+l.amount||0),0);if(s!==PS.R||PS.L.some(l=>!(+l.amount>0))){toast('جمع بخش‌ها باید برابر مبلغ بانکی باشد',true);return}psApply()};
function psApply(){const root=entries.find(e=>e.id===PS.root);if(!root){closeSheet();return}const fam=entries.filter(e=>e.id===root.id||e.splitOf===root.id).sort((a,b)=>a.id===root.id?-1:b.id===root.id?1:a.id-b.id);
  if(fam.some(e=>e.sentBid)){toast('یکی از بخش‌ها ارسال شده است',true);return}
  const now=new Date().toISOString(),ids=new Set(fam.map(e=>e.id)),rootSt=(root.settles||[]).reduce((a,z)=>a+(+z.amount||0),0);
  for(const k in drafts)drafts[k]=(drafts[k]||[]).map(p=>{if(p.sent||!(p.ids||[]).some(id=>ids.has(id)))return p;return{...p,ids:p.ids.filter(id=>!ids.has(id))}}).filter(p=>p.sent||p.ids.length);
  const keep=[];PS.L.forEach((l,i)=>{let e=fam[i];
    if(i===0){e.amount=rootSt+(+l.amount);e.updatedAt=now;e.updatedBy=who()}
    else if(e){e.amount=+l.amount;e.updatedAt=now;e.updatedBy=who()}
    else{e={id:nid++,splitOf:root.id,name:root.name,title:root.title||'',code:root.code||'',iban:root.iban||'',card:root.card||'',bank:root.bank||'',holder:root.holder||'',phone:root.phone||'',nid:root.nid||'',entryDate:root.entryDate,payDate:root.payDate||root.entryDate,amount:+l.amount,settles:[],note:'',createdBy:who(),updatedBy:who(),updatedAt:now};entries.push(e)}
    keep.push({e,src:l.src})});
  const drop=fam.slice(PS.L.length).map(e=>e.id);if(drop.length)trashIds(drop,'یکی کردن بخش‌های پرداخت');saveE();saveD();
  const k0=ldKey;ldKey=PS.pay;keep.forEach(({e,src})=>{const so=sources.find(z=>String(z.id)===String(src));if(so)moveTo([e.id],null,so)});ldKey=k0;
  logA('split',PS.L.length>1?'پرداخت از چند منبع':'یکی کردن بخش‌ها',PS.name+' | '+PS.L.map(l=>{const so=sources.find(z=>String(z.id)===String(l.src));return (so?so.name:'بدون منبع')+' '+fmt(l.amount)}).join('، '));
  const n=PS.L.length;PS=null;alloc=null;closeSheet();const v=$('view'),y=v.scrollTop;render();v.scrollTop=y;toast(n>1?'پرداخت بین '+toFa(n)+' منبع تقسیم شد':'بخش‌ها یکی شدند')}
/* ===== فاکتور فروش، کارتخوان‌ها و حساب‌ها، انتقال مانده بین مشتری‌ها (الگو: نرم‌افزار طلافروشی) =====
   همه داده‌ها داخل همان مجموعه custs ذخیره و همگام می‌شوند:
   - فاکتور = تراکنش type:'inv' در حساب مشتری (items، pays، total، gc = تبدیل مانده به طلایی)
   - انتقال مانده / تبدیل طلایی‌ریالی = تراکنش type:'xf' / 'cv' با r و g علامت‌دار (مثبت = بدهی ما)
   - کارتخوان و حساب بانکی خودمان = رکورد {sys:'ch', kind:'pos'|'bank'}؛ مانده = جمع تسویه‌های فاکتورها + حواله‌های ورودی − خروجی
   - گروه‌ها و فهرست کالاها = رکورد {sys:'cfg'} */
Object.assign(IC,{tag:'<path d="M3 12V4a1 1 0 0 1 1-1h8l9 9-9 9z"/><circle cx="7.5" cy="7.5" r="1.5"/>',inv:'<path d="M6 3h12v18l-3-2-3 2-3-2-3 2z"/><path d="M9 8h6M9 12h6M9 16h3"/>',card:'<rect x="3" y="6" width="18" height="13" rx="2.5"/><path d="M3 10h18M7 15h3"/>',swap:'<path d="M7 7h12l-3-3M17 17H5l3 3"/>',coin:'<ellipse cx="12" cy="7" rx="7" ry="3"/><path d="M5 7v5c0 1.7 3.1 3 7 3s7-1.3 7-3V7M5 12v5c0 1.7 3.1 3 7 3s7-1.3 7-3v-5"/>',cash:'<rect x="2.5" y="6" width="19" height="12" rx="2"/><circle cx="12" cy="12" r="2.5"/><path d="M6 9v.01M18 15v.01"/>',print:'<path d="M7 9V3h10v6"/><rect x="3" y="9" width="18" height="8" rx="2"/><path d="M7 14h10v7H7z"/>',ring:'<circle cx="12" cy="14" r="6"/><path d="M9 4h6l-1.5 3.6h-3z"/>'});
let cuRet='';
const ns=()=>new Date().toISOString();
/* ---------- تنظیمات مشترک: گروه‌ها و کالاها ---------- */
function cfgRec(make){let r=custs.find(c=>c.sys==='cfg'&&!c.del);if(!r&&make){r={id:nid++,sys:'cfg',name:'',groups:[],goods:[],txs:[],createdAt:ns()};custs.push(r)}return r}
const GOODS0=['انگشتر','النگو','دستبند','گردنبند','زنجیر','گوشواره','سرویس','نیم‌ست','پلاک','آویز','سکه','شمش','آبشده'];
