  <div class="rs${rest?'':' ok'}"><span>${rest>0?'مانده بدهی خریدار':rest<0?'اضافه پرداخت':'تسویه کامل'}</span><b>${rest?(t.gc?wFmt(t.gc.g)+' گرم طلا':fmt(Math.abs(rest))+' تومان'):'✓'}</b></div>
